INSERT INTO public.email_templates (nome, assunto, conteudo, etapa, categoria, variaveis) VALUES
('Confirmação de Candidatura', 'Candidatura recebida - {{vaga_titulo}}', E'Olá {{candidato_nome}},\n\nRecebemos sua candidatura para a vaga de {{vaga_titulo}}. Nosso time irá analisar seu perfil e entraremos em contato em breve.\n\nAtenciosamente,\nEquipe de RH', 'inscricao', 'candidatura', ARRAY['candidato_nome', 'vaga_titulo']),
('Convite para Entrevista', 'Convite para entrevista - {{vaga_titulo}}', E'Olá {{candidato_nome}},\n\nConvidamos você para uma entrevista para a vaga de {{vaga_titulo}}.\n\nData: {{data_entrevista}}\nHorário: {{hora_entrevista}}\nLocal: {{local_entrevista}}\n\nPor favor, confirme sua presença.\n\nAtenciosamente,\nEquipe de RH', 'entrevista', 'agendamento', ARRAY['candidato_nome', 'vaga_titulo', 'data_entrevista', 'hora_entrevista', 'local_entrevista']),
('Feedback Positivo', 'Parabéns! Próxima etapa - {{vaga_titulo}}', E'Olá {{candidato_nome}},\n\nParabéns! Você foi aprovado(a) na etapa de {{etapa_atual}} para a vaga de {{vaga_titulo}} e avançará para a próxima fase.\n\nAtenciosamente,\nEquipe de RH', 'aprovacao', 'feedback', ARRAY['candidato_nome', 'vaga_titulo', 'etapa_atual']),
('Reprovação', 'Retorno sobre sua candidatura - {{vaga_titulo}}', E'Olá {{candidato_nome}},\n\nAgradecemos seu interesse na vaga de {{vaga_titulo}}. Após cuidadosa análise, decidimos seguir com outros candidatos.\n\nDesejamos sucesso em sua carreira.\n\nAtenciosamente,\nEquipe de RH', 'reprovacao', 'feedback', ARRAY['candidato_nome', 'vaga_titulo']),
('Proposta de Emprego', 'Proposta de emprego - {{vaga_titulo}}', E'Olá {{candidato_nome}},\n\nApresentamos nossa proposta para a vaga de {{vaga_titulo}}.\n\nSalário: {{salario}}\nBenefícios: {{beneficios}}\nData de início: {{data_inicio}}\n\nAguardamos seu retorno.\n\nAtenciosamente,\nEquipe de RH', 'proposta', 'oferta', ARRAY['candidato_nome', 'vaga_titulo', 'salario', 'beneficios', 'data_inicio']);
